import 'package:flutter/material.dart';

String prettyState(String? s)=>switch(s){'draft'=>'Brouillon','in_review'=>'À relire','changes_requested'=>'Corrections demandées','approved'=>'Approuvé','published'=>'Publié','archived'=>'Archivé','rejected'=>'Rejeté','ingested'=>'Importé',_=>s??'—'};
String prettyRisk(String? s)=>switch(s){'medical'=>'Médical','high_stakes'=>'Enjeu élevé','standard'=>'Standard',_=>s??'—'};
String prettyRights(String? s)=>switch(s){'authorized'=>'Autorisé','public_domain'=>'Domaine public','internal_only'=>'Interne','restricted'=>'Restreint','unknown'=>'À vérifier',_=>s??'—'};
String prettyKind(String? s)=>switch(s){'course'=>'Cours','assessment'=>'Évaluation','question_set'=>'Banque de questions','summary'=>'Résumé','flashcards'=>'Flashcards','solution'=>'Solution','audio_script'=>'Script audio',_=>'Autre'};
String formatDate(dynamic raw){if(raw==null)return '—';final d=DateTime.tryParse(raw.toString())?.toLocal();if(d==null)return raw.toString();String two(int v)=>v.toString().padLeft(2,'0');return '${two(d.day)}/${two(d.month)}/${d.year} ${two(d.hour)}:${two(d.minute)}';}

Color stateColor(BuildContext c,String? s)=>switch(s){'published'=>Colors.green,'approved'=>Colors.teal,'in_review'=>Colors.indigo,'changes_requested'=>Colors.orange,'archived'=>Colors.grey,_=>Theme.of(c).colorScheme.primary};

class StatusPill extends StatelessWidget{
 final String label;final Color? color;final IconData? icon;const StatusPill(this.label,{super.key,this.color,this.icon});
 @override Widget build(BuildContext context){final c=color??Theme.of(context).colorScheme.primary;return Semantics(label:label,child:Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:6),decoration:BoxDecoration(color:c.withValues(alpha:.10),borderRadius:BorderRadius.circular(999),border:Border.all(color:c.withValues(alpha:.22))),child:Row(mainAxisSize:MainAxisSize.min,children:[if(icon!=null)...[Icon(icon,size:14,color:c),const SizedBox(width:5)],Text(label,style:Theme.of(context).textTheme.labelMedium?.copyWith(color:c,fontWeight:FontWeight.w700))])));}}

class StudioSection extends StatelessWidget{
 final String title;final String? subtitle;final Widget child;final Widget? trailing;const StudioSection({super.key,required this.title,this.subtitle,required this.child,this.trailing});
 @override Widget build(BuildContext context)=>Card(clipBehavior:Clip.antiAlias,child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w700)),if(subtitle!=null)...[const SizedBox(height:4),Text(subtitle!,style:Theme.of(context).textTheme.bodyMedium)] ])),if(trailing!=null)trailing!]),const SizedBox(height:18),child])));
}

class MetricCard extends StatelessWidget{
 final String value,label;final IconData icon;final Color? color;final VoidCallback? onTap;const MetricCard({super.key,required this.value,required this.label,required this.icon,this.color,this.onTap});
 @override Widget build(BuildContext context){final c=color??Theme.of(context).colorScheme.primary;return InkWell(borderRadius:BorderRadius.circular(20),onTap:onTap,child:Ink(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:Theme.of(context).colorScheme.surfaceContainerLow,borderRadius:BorderRadius.circular(20),border:Border.all(color:Theme.of(context).dividerColor.withValues(alpha:.18))),child:Row(children:[Container(width:46,height:46,decoration:BoxDecoration(color:c.withValues(alpha:.11),borderRadius:BorderRadius.circular(14)),child:Icon(icon,color:c)),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(value,style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),Text(label,maxLines:2,overflow:TextOverflow.ellipsis)]))])));}}

class StudioEmptyState extends StatelessWidget{final IconData icon;final String title,message;final Widget? action;const StudioEmptyState({super.key,required this.icon,required this.title,required this.message,this.action});@override Widget build(BuildContext c)=>Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:500),child:Padding(padding:const EdgeInsets.all(36),child:Column(mainAxisSize:MainAxisSize.min,children:[Container(width:74,height:74,decoration:BoxDecoration(color:Theme.of(c).colorScheme.primaryContainer.withValues(alpha:.55),borderRadius:BorderRadius.circular(24)),child:Icon(icon,size:36,color:Theme.of(c).colorScheme.onPrimaryContainer)),const SizedBox(height:18),Text(title,style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800),textAlign:TextAlign.center),const SizedBox(height:8),Text(message,style:Theme.of(c).textTheme.bodyMedium,textAlign:TextAlign.center),if(action!=null)...[const SizedBox(height:20),action!]]))));}

class StudioErrorState extends StatelessWidget{final VoidCallback onRetry;final String? message;const StudioErrorState({super.key,required this.onRetry,this.message});@override Widget build(BuildContext c)=>StudioEmptyState(icon:Icons.cloud_off_rounded,title:'Impossible de charger',message:message??'Vérifie la connexion puis réessaie.',action:FilledButton.icon(onPressed:onRetry,icon:const Icon(Icons.refresh),label:const Text('Réessayer')));}

class GateTile extends StatelessWidget{final Map<String,dynamic> gate;const GateTile({super.key,required this.gate});@override Widget build(BuildContext c){final ok=gate['passed']==true;final color=ok?Colors.green:Theme.of(c).colorScheme.error;return ListTile(dense:true,contentPadding:EdgeInsets.zero,leading:Icon(ok?Icons.check_circle:Icons.error_outline,color:color),title:Text(gate['label']?.toString()??''),subtitle:Text(gate['detail']?.toString()??''),trailing:StatusPill(ok?'OK':'Bloquant',color:color));}}
